"""Writes generated pytest test code to files in the output directory."""

import os
from pathlib import Path


HEADER = """\
# =============================================================
# Generated by TestGhost v2 — do not edit manually
# Re-generate: testghost generate --session <session_id>
# =============================================================

"""


def write_test_file(cluster_label: str, generated_code: str, output_dir: str) -> str:
    """
    Write generated code to output/tests/test_{cluster_label}.py.
    Appends if file exists (multiple requests in same cluster).
    Returns the file path.
    """
    tests_dir = Path(output_dir) / "tests"
    tests_dir.mkdir(parents=True, exist_ok=True)

    safe_label = cluster_label.replace(" ", "_").replace("-", "_").lower()
    file_path = tests_dir / f"test_{safe_label}.py"

    if not file_path.exists():
        file_path.write_text(HEADER + generated_code + "\n", encoding="utf-8")
    else:
        existing = file_path.read_text(encoding="utf-8")
        file_path.write_text(existing + "\n\n" + generated_code + "\n", encoding="utf-8")

    return str(file_path)
